cat > /tmp/oracle.mjs <<'EOF'
// Oracle: reimplements inferred behavior. Prints stdout, stderr(normalized), exit code.
const argv = process.argv.slice(2);
const SPEC = ['--k1','--v1','--k2','--v2'];
const got = {};
for (let i=0;i<argv.length;i++){
  const a = argv[i]; let name=null, val=null;
  const eq = a.indexOf('=');
  if (a.startsWith('--') && eq>0){ name=a.slice(0,eq); val=a.slice(eq+1); }
  else if (a.startsWith('--')){ name=a; val=argv[++i]; }
  else { process.stderr.write('UNSUPPORTED\n'); process.exit(9); }
  if (!SPEC.includes(name)) { process.stderr.write('UNSUPPORTED\n'); process.exit(9); }
  got[name]=val;             // LAST OCCURRENCE WINS
}
for (const s of SPEC) if (!(s in got)) { process.stderr.write('MISSING\n'); process.exit(9); }
const k1=got['--k1'], k2=got['--k2'];
const v1=parseInt(got['--v1'],10), v2=parseInt(got['--v2'],10);

// ordered pairs, SOURCE order: k1 then k2, k2 overwrites k1's slot if same key
let e=[[k1,v1]];
const idx=e.findIndex(([k])=>k===k2);
if (idx>=0) e[idx][1]=v2; else e.push([k2,v2]);

const fmt=(arr)=>'bidict({'+arr.map(([k,v])=>`'${k}': ${v}`).join(', ')+'})';
const out=[]; 
// value-duplication check at construction
const vals=e.map(([,v])=>v);
if (new Set(vals).size !== vals.length){
  process.stdout.write(out.join(''));
  process.stderr.write(`bidict.ValueDuplicationError: ${vals[1]}\n`); process.exit(1);
}
let b2 = e.map(([k,v])=>[k,v]);   // copy snapshot
out.push(fmt(b2)+'\n');
// b1['new']=999
let b1=e;
const ni=b1.findIndex(([k])=>k==='new');
const vi=b1.findIndex(([,v])=>v===999);
if (ni>=0 && vi>=0 && ni!==vi){ process.stdout.write(out.join('')); process.stderr.write(`bidict.KeyAndValueDuplicationError: ('new', 999)\n`); process.exit(1); }
if (ni<0 && vi>=0){ process.stdout.write(out.join('')); process.stderr.write(`bidict.ValueDuplicationError: 999\n`); process.exit(1); }
if (ni>=0) b1[ni][1]=999; else b1.push(['new',999]);
out.push(fmt(b1)+'\n'); out.push(fmt(b2)+'\n');
const hit=b2.find(([,v])=>v===v1);
if (!hit){ process.stdout.write(out.join('')); process.stderr.write(`KeyError: ${v1}\n`); process.exit(1); }
out.push(hit[0]+'\n');
process.stdout.write(out.join('')); process.exit(0);
EOF
echo ok
